import katex from 'katex'
import { useMemo } from 'react'

/** Renders a LaTeX expression. Output is generated by KaTeX, not user input. */
export function Katex({ expression, display = true }: { expression: string; display?: boolean }) {
  const html = useMemo(
    () =>
      katex.renderToString(expression, {
        displayMode: display,
        throwOnError: false,
        output: 'html',
      }),
    [expression, display],
  )
  return <span dangerouslySetInnerHTML={{ __html: html }} />
}
